let hpeLibraryQuery='',hpeLibraryCategory='';
const hpeLibraryNormalize=s=>String(s).toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function hpeLibraryAllowed(){return role==='personal'&&hpeProfile?.role==='personal'}
function hpeLibraryScreen(){return heading('MODELOS PARA O PERSONAL','Biblioteca de treinos','Escolha uma ficha, revise a prescrição e personalize para seu aluno.')+`<section class="card"><div class="inline"><label>Buscar por exercício ou divisão<input type="search" value="${esc(hpeLibraryQuery)}" placeholder="Ex.: glúteos, supino, inferiores" oninput="hpeFilterLibrary(this.value)"></label><label>Categoria<select onchange="hpeLibraryCategory=this.value;hpeFilterLibrary(hpeLibraryQuery)"><option value="">Todas</option ${hpeLibraryCategory==='Musculação'?'selected':''}>Musculação</option ${hpeLibraryCategory==='Adaptado'?'selected':''}>Adaptado</option></select></label></div><p id="library-count" role="status"></p><p class="note">Modelos importados do Drive, sem dados pessoais. Campos ausentes precisam ser preenchidos pelo personal. Cargas começam em zero para ajuste individual.</p></section><div id="library-cards" class="grid library-grid">${window.hpeTrainingModels.map(m=>`<section class="card library-card" data-model="${m.id}"><span class="tag">${esc(m.category)} · ${m.blocks.length} DIVISÕES</span><h2>${esc(m.title)}</h2><p>${m.blocks.reduce((n,b)=>n+b.exercises.length,0)} exercícios${m.duration?` · ${m.duration} semanas`:''}</p><p>${m.blocks.map(b=>esc(b.title)).join(' · ')}</p><button class="primary" onclick="hpeReviewModel('${m.id}')">Ver e personalizar ↗</button></section>`).join('')}</div><section id="library-empty" class="card empty" hidden>Nenhum modelo encontrado. Tente outro exercício ou categoria.</section>`}
window.hpeFilterLibrary=value=>{hpeLibraryQuery=value;const q=hpeLibraryNormalize(value);let count=0;document.querySelectorAll('[data-model]').forEach(el=>{const m=window.hpeTrainingModels.find(x=>x.id===el.dataset.model);el.hidden=!!((hpeLibraryCategory&&m.category!==hpeLibraryCategory)||!hpeLibraryNormalize(JSON.stringify(m.blocks)+m.title).includes(q));if(!el.hidden)count++});$('#library-count').textContent=`${count} modelos disponíveis`;$('#library-empty').hidden=count>0};
window.hpeReviewModel=id=>{
 if(!hpeLibraryAllowed())return;const m=window.hpeTrainingModels.find(x=>x.id===id);if(!m)return;
 const students=visibleStudents();
 modal(`<span class="eyebrow">PERSONALIZE ANTES DE APLICAR</span><h2>${esc(m.title)}</h2><p>${m.notes.map(esc).join(' ')}</p><details><summary>Consultar prescrição original da ficha</summary><pre class="library-reference">${esc(m.reference)}</pre></details>${!students.length?'<p class="empty">Cadastre um aluno em Meus alunos para aplicar uma ficha.</p>':''}<form id="library-apply"><label>Aluno<select name="student" required>${students.map(s=>`<option value="${s.id}" ${s.id===student?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Como aplicar<select name="mode"><option value="new">Adicionar novas divisões (preserva o plano atual)</option><option value="replace">Substituir a divisão selecionada do aluno</option></select></label><div class="inline"><label>Descanso para campos em branco (segundos)<input id="library-rest-default" type="number" min="0" max="600" value="60"></label><button type="button" onclick="hpeFillModelRest()">Preencher descansos em branco</button></div><p class="note">Para substituir, selecione apenas uma divisão abaixo. Demais divisões e histórico são preservados.</p>${m.blocks.map((b,bi)=>`<section class="library-block"><label class="library-check"><input type="checkbox" name="block" value="${bi}" checked onchange="hpeLibraryToggleBlock(${bi},this.checked)"> Incluir ${esc(b.title)}</label><fieldset id="library-fields-${bi}"><label>Nome da divisão<input name="title-${bi}" value="${esc(b.title)}" maxlength="140" required></label>${b.exercises.map((e,ei)=>{const k=bi+'-'+ei;return `<details class="library-exercise"><summary>${ei+1}. ${esc(e.name)} · ${esc(e.prescription||'Completar prescrição')}</summary><label>Exercício<input name="name-${k}" value="${esc(e.name)}" maxlength="160" required></label><div class="inline"><label>Séries<input name="sets-${k}" type="number" min="1" max="20" value="${e.sets??''}" required></label><label>Repetições ou tempo<input name="reps-${k}" value="${esc(e.repsText)}" placeholder="12, 15/12/10, falha ou 30 segundos" maxlength="150" required></label></div><div class="inline"><label>Descanso (segundos)<input name="rest-${k}" type="number" min="0" max="600" value="${e.rest??''}" required></label><label>Carga inicial (kg)<input name="weight-${k}" type="number" min="0" max="1000" step="0.5" value="0" required></label></div><label>Orientação e método<textarea name="notes-${k}" maxlength="2000">${esc(e.notes)}</textarea></label><label>Vídeo (HTTPS, opcional)<input name="video-${k}" type="url" value="${esc(e.video)}"></label></details>`}).join('')}</fieldset></section>`).join('')}<label class="library-check"><input name="reviewed" type="checkbox" required> Revisei a ficha e ajustei a prescrição para este aluno.</label><label class="library-check"><input name="replace-confirm" type="checkbox"> Se escolhi substituir, confirmo a troca da divisão atual.</label><p id="library-error" role="alert"></p><button class="primary" ${students.length?'':'disabled'}>Aplicar ficha ao aluno</button></form>`);
 $('#modal').classList.add('library-modal');$('#library-apply').addEventListener('invalid',event=>{event.target.closest('details')?.setAttribute('open','')},true);$('#library-apply').onsubmit=e=>hpeApplyModel(e,m);
};
window.hpeFillModelRest=()=>{const v=Number($('#library-rest-default').value);if(!Number.isFinite(v)||v<0||v>600)return;$('#library-apply').querySelectorAll('input[name^="rest-"]').forEach(input=>{if(!input.value)input.value=v})};
window.hpeLibraryToggleBlock=(i,enabled)=>{$('#library-fields-'+i).disabled=!enabled};
function hpeBuildProgram(m,f){
 const blocks=f.getAll('block').map(Number);if(!blocks.length)throw Error('Selecione pelo menos uma divisão.');
 return blocks.map(bi=>{const b=m.blocks[bi];if(!b)throw Error('Divisão inválida.');return {title:String(f.get('title-'+bi)||'').trim(),exercises:b.exercises.map((original,ei)=>{const k=bi+'-'+ei;const name=String(f.get('name-'+k)||'').trim(),reps=String(f.get('reps-'+k)||'').trim(),sets=Number(f.get('sets-'+k)),rest=Number(f.get('rest-'+k)),weight=Number(f.get('weight-'+k)),video=String(f.get('video-'+k)||'').trim();if(!name||!reps||!String(f.get('rest-'+k)||'').trim()||!Number.isInteger(sets)||sets<1||sets>20||!Number.isFinite(rest)||rest<0||rest>600||!Number.isFinite(weight)||weight<0||weight>1000||video&&!/^https:\/\//i.test(video))throw Error('Preencha séries, repetições e descanso de todos os exercícios selecionados. Vídeos devem usar HTTPS.');return {name,sets,reps,rest,weight,video,gif:'',notes:String(f.get('notes-'+k)||''),modelId:m.id,modelNotes:m.notes.join(' '),prescription:`${sets} x ${reps}`}})}});
}
function hpeApplyModel(event,m){
 event.preventDefault();if(!hpeLibraryAllowed())return;
 try{const f=new FormData(event.target),id=Number(f.get('student'));if(!visibleStudents().some(s=>s.id===id))throw Error('Escolha um aluno vinculado a você.');if(!f.get('reviewed'))throw Error('Revise a ficha antes de aplicar.');const program=hpeBuildProgram(m,f),replace=f.get('mode')==='replace';if(replace&&(program.length!==1||!f.get('replace-confirm')))throw Error('Para substituir, escolha uma única divisão e confirme a troca.');
 data.alternatePlans??={};data.blockNames??={};data.alternatePlans[id]??={};data.blockNames[id]??={};
 const keys=['A',...Object.keys(data.alternatePlans[id])];let next=[];
 if(replace)next=[window.currentTrainingBlock||'A'];else{for(let i=0;i<26&&next.length<program.length;i++){const key=String.fromCharCode(65+i),p=key==='A'?data.plans[id]:data.alternatePlans[id][key];if(!p?.length&&!data.blockNames[id][key])next.push(key)}if(next.length!==program.length)throw Error('Não há divisões livres suficientes. Aplique menos divisões por vez.');}
 program.forEach((p,i)=>{const key=next[i];if(key==='A')data.plans[id]=p.exercises;else data.alternatePlans[id][key]=p.exercises;data.blockNames[id][key]=p.title});student=id;window.currentTrainingBlock=next[0];done.clear();activeExercise=0;seriesEntries=[];save();$('#modal').close();$('#modal').classList.remove('library-modal');trainingTab='lista';go('treinos');toast('Ficha aplicada. Confira os indicadores de sincronização do aluno.');
 }catch(error){$('#library-error').textContent=error.message;const invalid=$('#library-apply').querySelector(':invalid');if(invalid){invalid.closest('details')?.setAttribute('open','');invalid.focus()}}
}
const libraryRender=render;render=function(){libraryRender();if(!hpeLibraryAllowed())return;$('#nav').insertAdjacentHTML('beforeend',`<button class="${page==='biblioteca'?'active':''}" onclick="go('biblioteca')">▤ &nbsp; Biblioteca de treinos</button>`);if(page==='biblioteca'){$('#content').innerHTML=hpeLibraryScreen();hpeFilterLibrary(hpeLibraryQuery)}if(page==='treinos')$('#content').insertAdjacentHTML('afterbegin','<section class="card"><div class="row"><div><span class="eyebrow">FICHAS PRONTAS</span><h2>Um ponto de partida para cada aluno.</h2></div><button class="primary" onclick="go(\'biblioteca\')">Abrir biblioteca ↗</button></div></section>')};

$('#modal').addEventListener('close',()=>$('#modal').classList.remove('library-modal'));
